import sys

n, m = map(int, sys.stdin.readline().split())
w, h = min(n, m), max(n, m)

size = 1 << w
full = size - 1
inf = 10**9

popcount = [x.bit_count() for x in range(size)]
cover = [
    (mask | (mask << 1) | (mask >> 1)) & full
    for mask in range(size)
]

dp = [[inf] * size for _ in range(size)]
for mask in range(size):
    dp[0][mask] = popcount[mask]

for _ in range(1, h):
    ndp = [[inf] * size for _ in range(size)]

    for previous in range(size):
        best = [dp[above][previous] for above in range(size)]

        for bit in range(w):
            bit_mask = 1 << bit
            for mask in range(size):
                if not (mask & bit_mask):
                    value = best[mask | bit_mask]
                    if value < best[mask]:
                        best[mask] = value

        horizontal = cover[previous]
        row = ndp[previous]
        for current in range(size):
            needed = full & ~(horizontal | current)
            value = best[needed] + popcount[current]
            row[current] = value

    dp = ndp

minimum_occupied = inf
for above in range(size):
    for last in range(size):
        if (above | cover[last]) == full:
            minimum_occupied = min(minimum_occupied, dp[above][last])

print(n * m - minimum_occupied)

