import sys

def main():
    n, m = map(int, sys.stdin.readline().split())
    w, h = min(n, m), max(n, m)

    size = 1 << w
    full = size - 1
    popcount = [x.bit_count() for x in range(size)]
    cover = [(x | (x << 1) | (x >> 1)) & full for x in range(size)]

    dp = {mask: popcount[mask] for mask in range(size)}

    for _ in range(1, h):
        ndp = {}
        for state, cost in dp.items():
            above = state >> w
            previous = state & full
            missing = full & ~(above | cover[previous])
            free = full ^ missing

            subset = free
            while True:
                current = missing | subset
                new_state = (previous << w) | current
                new_cost = cost + popcount[current]
                if new_cost < ndp.get(new_state, 10**9):
                    ndp[new_state] = new_cost
                if subset == 0:
                    break
                subset = (subset - 1) & free
        dp = ndp

    minimum = min(
        cost
        for state, cost in dp.items()
        if ((state >> w) | cover[state & full]) == full
    )

    print(n * m - minimum)

if __name__ == "__main__":
    main()
